#[cfg(feature = "visual-validation")]
struct VisualAiStudioCaptureTask {
    receiver: mpsc::Receiver<Result<(), String>>,
    started_at: Instant,
}

#[cfg(feature = "visual-validation")]
impl VisualAiStudioCaptureTask {
    fn spawn(path: PathBuf) -> Self {
        let (sender, receiver) = mpsc::channel();
        std::thread::spawn(move || {
            let result = capture_ai_studio_native_window(&path);
            let _ = sender.send(result);
        });
        Self {
            receiver,
            started_at: Instant::now(),
        }
    }

    fn poll(&self) -> Option<Result<(), String>> {
        match self.receiver.try_recv() {
            Ok(result) => Some(result),
            Err(mpsc::TryRecvError::Empty) => None,
            Err(mpsc::TryRecvError::Disconnected) => {
                Some(Err("AI Studio native-window capture worker disconnected".to_owned()))
            }
        }
    }

    fn timed_out(&self) -> bool {
        self.started_at.elapsed() >= Duration::from_secs(15)
    }
}

